export const getActionActivateTypeRoute = createRoute({
  method: 'get',
  path: '/#Action=ActivateType',
  description:
    '<p>Activates a public third-party extension, making it available for use in stack templates. For more information, see <a href="https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/registry-public.html">Using public extensions</a> in the <i>CloudFormation User Guide</i>.</p> <p>Once you have activated a public third-party extension in your account and Region, use <a href="https://docs.aws.amazon.com/AWSCloudFormation/latest/APIReference/API_SetTypeConfiguration.html">SetTypeConfiguration</a> to specify configuration properties for the extension. For more information, see <a href="https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/registry-register.html#registry-set-configuration">Configuring extensions at the account level</a> in the <i>CloudFormation User Guide</i>.</p>',
  operationId: 'GET_ActivateType',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['LogRoleArn', ['LoggingConfig']],
          ['LogGroupName', ['LoggingConfig']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          Type: z
            .enum(['RESOURCE', 'MODULE', 'HOOK'])
            .exactOptional()
            .openapi({
              param: {
                name: 'Type',
                in: 'query',
                required: false,
                description:
                  '<p>The extension type.</p> <p>Conditional: You must specify <code>PublicTypeArn</code>, or <code>TypeName</code>, <code>Type</code>, and <code>PublisherId</code>.</p>',
                schema: { type: 'string', enum: ['RESOURCE', 'MODULE', 'HOOK'] },
              },
            }),
          PublicTypeArn: z
            .string()
            .regex(
              /arn:aws[A-Za-z0-9-]{0,64}:cloudformation:[A-Za-z0-9-]{1,64}::type\/.+\/[0-9a-zA-Z]{12,40}\/.+/,
            )
            .max(1024)
            .exactOptional()
            .openapi({
              param: {
                name: 'PublicTypeArn',
                in: 'query',
                required: false,
                description:
                  '<p>The Amazon Resource Name (ARN) of the public extension.</p> <p>Conditional: You must specify <code>PublicTypeArn</code>, or <code>TypeName</code>, <code>Type</code>, and <code>PublisherId</code>.</p>',
                schema: {
                  type: 'string',
                  pattern:
                    'arn:aws[A-Za-z0-9-]{0,64}:cloudformation:[A-Za-z0-9-]{1,64}::type/.+/[0-9a-zA-Z]{12,40}/.+',
                  maxLength: 1024,
                },
              },
            }),
          PublisherId: z
            .string()
            .regex(/[0-9a-zA-Z]{12,40}/)
            .min(1)
            .max(40)
            .exactOptional()
            .openapi({
              param: {
                name: 'PublisherId',
                in: 'query',
                required: false,
                description:
                  '<p>The ID of the extension publisher.</p> <p>Conditional: You must specify <code>PublicTypeArn</code>, or <code>TypeName</code>, <code>Type</code>, and <code>PublisherId</code>.</p>',
                schema: {
                  type: 'string',
                  pattern: '[0-9a-zA-Z]{12,40}',
                  minLength: 1,
                  maxLength: 40,
                },
              },
            }),
          TypeName: z
            .string()
            .regex(/[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}(::MODULE){0,1}/)
            .min(10)
            .max(204)
            .exactOptional()
            .openapi({
              param: {
                name: 'TypeName',
                in: 'query',
                required: false,
                description:
                  '<p>The name of the extension.</p> <p>Conditional: You must specify <code>PublicTypeArn</code>, or <code>TypeName</code>, <code>Type</code>, and <code>PublisherId</code>.</p>',
                schema: {
                  type: 'string',
                  pattern: '[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}(::MODULE){0,1}',
                  minLength: 10,
                  maxLength: 204,
                },
              },
            }),
          TypeNameAlias: z
            .string()
            .regex(/[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}(::MODULE){0,1}/)
            .min(10)
            .max(204)
            .exactOptional()
            .openapi({
              param: {
                name: 'TypeNameAlias',
                in: 'query',
                required: false,
                description:
                  '<p>An alias to assign to the public extension, in this account and Region. If you specify an alias for the extension, CloudFormation treats the alias as the extension type name within this account and Region. You must use the alias to refer to the extension in your templates, API calls, and CloudFormation console.</p> <p>An extension alias must be unique within a given account and Region. You can activate the same public resource multiple times in the same account and Region, using different type name aliases.</p>',
                schema: {
                  type: 'string',
                  pattern: '[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}(::MODULE){0,1}',
                  minLength: 10,
                  maxLength: 204,
                },
              },
            }),
          AutoUpdate: z
            .stringbool()
            .exactOptional()
            .openapi({
              param: {
                name: 'AutoUpdate',
                in: 'query',
                required: false,
                description:
                  '<p>Whether to automatically update the extension in this account and Region when a new <i>minor</i> version is published by the extension publisher. Major versions released by the publisher must be manually updated.</p> <p>The default is <code>true</code>.</p>',
                schema: { type: 'boolean' },
              },
            }),
          LoggingConfig: z
            .object({
              LogRoleArn: RoleArnSchema.and(
                z
                  .any()
                  .openapi({
                    description:
                      'The Amazon Resource Name (ARN) of the role that CloudFormation should assume when sending log entries to CloudWatch Logs.',
                  }),
              ),
              LogGroupName: LogGroupNameSchema.and(
                z
                  .any()
                  .openapi({
                    description:
                      "The Amazon CloudWatch Logs group to which CloudFormation sends error logging information when invoking the extension's handlers.",
                  }),
              ),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'LoggingConfig',
                in: 'query',
                required: false,
                description: 'Contains logging configuration information for an extension.',
                schema: {
                  type: 'object',
                  required: ['LogRoleArn', 'LogGroupName'],
                  properties: {
                    LogRoleArn: {
                      allOf: [
                        { $ref: '#/components/schemas/RoleArn' },
                        {
                          description:
                            'The Amazon Resource Name (ARN) of the role that CloudFormation should assume when sending log entries to CloudWatch Logs.',
                        },
                      ],
                    },
                    LogGroupName: {
                      allOf: [
                        { $ref: '#/components/schemas/LogGroupName' },
                        {
                          description:
                            "The Amazon CloudWatch Logs group to which CloudFormation sends error logging information when invoking the extension's handlers.",
                        },
                      ],
                    },
                  },
                  description: 'Contains logging configuration information for an extension.',
                },
              },
              required: ['LogRoleArn', 'LogGroupName'],
              description: 'Contains logging configuration information for an extension.',
            }),
          ExecutionRoleArn: z
            .string()
            .regex(/arn:.+:iam::[0-9]{12}:role\/.+/)
            .min(1)
            .max(256)
            .exactOptional()
            .openapi({
              param: {
                name: 'ExecutionRoleArn',
                in: 'query',
                required: false,
                description: 'The name of the IAM execution role to use to activate the extension.',
                schema: {
                  type: 'string',
                  pattern: 'arn:.+:iam::[0-9]{12}:role/.+',
                  minLength: 1,
                  maxLength: 256,
                },
              },
            }),
          VersionBump: z
            .enum(['MAJOR', 'MINOR'])
            .exactOptional()
            .openapi({
              param: {
                name: 'VersionBump',
                in: 'query',
                required: false,
                description:
                  '<p>Manually updates a previously-activated type to a new major or minor version, if available. You can also use this parameter to update the value of <code>AutoUpdate</code>.</p> <ul> <li> <p> <code>MAJOR</code>: CloudFormation updates the extension to the newest major version, if one is available.</p> </li> <li> <p> <code>MINOR</code>: CloudFormation updates the extension to the newest minor version, if one is available.</p> </li> </ul>',
                schema: { type: 'string', enum: ['MAJOR', 'MINOR'] },
              },
            }),
          MajorVersion: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int().min(1).max(100000),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'MajorVersion',
                in: 'query',
                required: false,
                description:
                  '<p>The major version of this extension you want to activate, if multiple major versions are available. The default is the latest major version. CloudFormation uses the latest available <i>minor</i> version of the major version selected.</p> <p>You can specify <code>MajorVersion</code> or <code>VersionBump</code>, but not both.</p>',
                schema: { type: 'integer', minimum: 1, maximum: 100000 },
              },
            }),
          Action: z
            .literal('ActivateType')
            .openapi({
              param: {
                name: 'Action',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['ActivateType'] },
              },
            }),
          Version: z
            .literal('2010-05-15')
            .openapi({
              param: {
                name: 'Version',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['2010-05-15'] },
              },
            }),
        }),
      ),
  },
  responses: {
    200: { description: 'Success', content: { 'text/xml': { schema: ActivateTypeOutputSchema } } },
    480: {
      description: 'CFNRegistryException',
      content: { 'text/xml': { schema: CFNRegistryExceptionSchema } },
    },
    481: {
      description: 'TypeNotFoundException',
      content: { 'text/xml': { schema: TypeNotFoundExceptionSchema } },
    },
  },
})

