export const getActionDeactivateTypeRoute = createRoute({
  method: 'get',
  path: '/#Action=DeactivateType',
  description:
    "<p>Deactivates a public extension that was previously activated in this account and Region.</p> <p>Once deactivated, an extension can't be used in any CloudFormation operation. This includes stack update operations where the stack template includes the extension, even if no updates are being made to the extension. In addition, deactivated extensions aren't automatically updated if a new version of the extension is released.</p>",
  operationId: 'GET_DeactivateType',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      TypeName: z
        .string()
        .regex(/[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}(::MODULE){0,1}/)
        .min(10)
        .max(204)
        .exactOptional()
        .openapi({
          param: {
            name: 'TypeName',
            in: 'query',
            required: false,
            description:
              '<p>The type name of the extension, in this account and Region. If you specified a type name alias when enabling the extension, use the type name alias.</p> <p>Conditional: You must specify either <code>Arn</code>, or <code>TypeName</code> and <code>Type</code>.</p>',
            schema: {
              type: 'string',
              pattern: '[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}(::MODULE){0,1}',
              minLength: 10,
              maxLength: 204,
            },
          },
        }),
      Type: z
        .enum(['RESOURCE', 'MODULE', 'HOOK'])
        .exactOptional()
        .openapi({
          param: {
            name: 'Type',
            in: 'query',
            required: false,
            description:
              '<p>The extension type.</p> <p>Conditional: You must specify either <code>Arn</code>, or <code>TypeName</code> and <code>Type</code>.</p>',
            schema: { type: 'string', enum: ['RESOURCE', 'MODULE', 'HOOK'] },
          },
        }),
      Arn: z
        .string()
        .regex(/arn:aws[A-Za-z0-9-]{0,64}:cloudformation:[A-Za-z0-9-]{1,64}:[0-9]{12}:type\/.+/)
        .max(1024)
        .exactOptional()
        .openapi({
          param: {
            name: 'Arn',
            in: 'query',
            required: false,
            description:
              '<p>The Amazon Resource Name (ARN) for the extension, in this account and Region.</p> <p>Conditional: You must specify either <code>Arn</code>, or <code>TypeName</code> and <code>Type</code>.</p>',
            schema: {
              type: 'string',
              pattern:
                'arn:aws[A-Za-z0-9-]{0,64}:cloudformation:[A-Za-z0-9-]{1,64}:[0-9]{12}:type/.+',
              maxLength: 1024,
            },
          },
        }),
      Action: z
        .literal('DeactivateType')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['DeactivateType'] },
          },
        }),
      Version: z
        .literal('2010-05-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2010-05-15'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: DeactivateTypeOutputSchema } },
    },
    480: {
      description: 'CFNRegistryException',
      content: { 'text/xml': { schema: CFNRegistryExceptionSchema } },
    },
    481: {
      description: 'TypeNotFoundException',
      content: { 'text/xml': { schema: TypeNotFoundExceptionSchema } },
    },
  },
})

