export const getActionDeleteChangeSetRoute = createRoute({
  method: 'get',
  path: '/#Action=DeleteChangeSet',
  description:
    '<p>Deletes the specified change set. Deleting change sets ensures that no one executes the wrong change set.</p> <p>If the call successfully completes, CloudFormation successfully deleted the change set.</p> <p>If <code>IncludeNestedStacks</code> specifies <code>True</code> during the creation of the nested change set, then <code>DeleteChangeSet</code> will delete all change sets that belong to the stacks hierarchy and will also delete all change sets for nested stacks with the status of <code>REVIEW_IN_PROGRESS</code>.</p>',
  operationId: 'GET_DeleteChangeSet',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      ChangeSetName: z
        .string()
        .regex(/[a-zA-Z][-a-zA-Z0-9]*|arn:[-a-zA-Z0-9:\/]*/)
        .min(1)
        .max(1600)
        .openapi({
          param: {
            name: 'ChangeSetName',
            in: 'query',
            required: true,
            description:
              'The name or Amazon Resource Name (ARN) of the change set that you want to delete.',
            schema: {
              type: 'string',
              pattern: '[a-zA-Z][-a-zA-Z0-9]*|arn:[-a-zA-Z0-9:/]*',
              minLength: 1,
              maxLength: 1600,
            },
          },
        }),
      StackName: z
        .string()
        .regex(/([a-zA-Z][-a-zA-Z0-9]*)|(arn:\b(aws|aws-us-gov|aws-cn)\b:[-a-zA-Z0-9:\/._+]*)/)
        .min(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'StackName',
            in: 'query',
            required: false,
            description:
              "If you specified the name of a change set to delete, specify the stack name or Amazon Resource Name (ARN) that's associated with it.",
            schema: {
              type: 'string',
              pattern:
                '([a-zA-Z][-a-zA-Z0-9]*)|(arn:\\b(aws|aws-us-gov|aws-cn)\\b:[-a-zA-Z0-9:/._+]*)',
              minLength: 1,
            },
          },
        }),
      Action: z
        .literal('DeleteChangeSet')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['DeleteChangeSet'] },
          },
        }),
      Version: z
        .literal('2010-05-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2010-05-15'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: DeleteChangeSetOutputSchema } },
    },
    480: {
      description: 'InvalidChangeSetStatusException',
      content: { 'text/xml': { schema: InvalidChangeSetStatusExceptionSchema } },
    },
  },
})

