export const getActionDescribeTypeRoute = createRoute({
  method: 'get',
  path: '/#Action=DescribeType',
  description:
    '<p>Returns detailed information about an extension that has been registered.</p> <p>If you specify a <code>VersionId</code>, <code>DescribeType</code> returns information about that specific extension version. Otherwise, it returns information about the default extension version.</p>',
  operationId: 'GET_DescribeType',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      Type: z
        .enum(['RESOURCE', 'MODULE', 'HOOK'])
        .exactOptional()
        .openapi({
          param: {
            name: 'Type',
            in: 'query',
            required: false,
            description:
              '<p>The kind of extension.</p> <p>Conditional: You must specify either <code>TypeName</code> and <code>Type</code>, or <code>Arn</code>.</p>',
            schema: { type: 'string', enum: ['RESOURCE', 'MODULE', 'HOOK'] },
          },
        }),
      TypeName: z
        .string()
        .regex(/[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}(::MODULE){0,1}/)
        .min(10)
        .max(204)
        .exactOptional()
        .openapi({
          param: {
            name: 'TypeName',
            in: 'query',
            required: false,
            description:
              '<p>The name of the extension.</p> <p>Conditional: You must specify either <code>TypeName</code> and <code>Type</code>, or <code>Arn</code>.</p>',
            schema: {
              type: 'string',
              pattern: '[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}::[A-Za-z0-9]{2,64}(::MODULE){0,1}',
              minLength: 10,
              maxLength: 204,
            },
          },
        }),
      Arn: z
        .string()
        .regex(/arn:aws[A-Za-z0-9-]{0,64}:cloudformation:[A-Za-z0-9-]{1,64}:([0-9]{12})?:type\/.+/)
        .max(1024)
        .exactOptional()
        .openapi({
          param: {
            name: 'Arn',
            in: 'query',
            required: false,
            description:
              '<p>The Amazon Resource Name (ARN) of the extension.</p> <p>Conditional: You must specify either <code>TypeName</code> and <code>Type</code>, or <code>Arn</code>.</p>',
            schema: {
              type: 'string',
              pattern:
                'arn:aws[A-Za-z0-9-]{0,64}:cloudformation:[A-Za-z0-9-]{1,64}:([0-9]{12})?:type/.+',
              maxLength: 1024,
            },
          },
        }),
      VersionId: z
        .string()
        .regex(/[A-Za-z0-9-]+/)
        .min(1)
        .max(128)
        .exactOptional()
        .openapi({
          param: {
            name: 'VersionId',
            in: 'query',
            required: false,
            description:
              '<p>The ID of a specific version of the extension. The version ID is the value at the end of the Amazon Resource Name (ARN) assigned to the extension version when it is registered.</p> <p>If you specify a <code>VersionId</code>, <code>DescribeType</code> returns information about that specific extension version. Otherwise, it returns information about the default extension version.</p>',
            schema: { type: 'string', pattern: '[A-Za-z0-9-]+', minLength: 1, maxLength: 128 },
          },
        }),
      PublisherId: z
        .string()
        .regex(/[0-9a-zA-Z]{12,40}/)
        .min(1)
        .max(40)
        .exactOptional()
        .openapi({
          param: {
            name: 'PublisherId',
            in: 'query',
            required: false,
            description:
              '<p>The publisher ID of the extension publisher.</p> <p>Extensions provided by Amazon Web Services are not assigned a publisher ID.</p>',
            schema: { type: 'string', pattern: '[0-9a-zA-Z]{12,40}', minLength: 1, maxLength: 40 },
          },
        }),
      PublicVersionNumber: z
        .string()
        .regex(/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(.*)$/)
        .min(5)
        .exactOptional()
        .openapi({
          param: {
            name: 'PublicVersionNumber',
            in: 'query',
            required: false,
            description: 'The version number of a public third-party extension.',
            schema: {
              type: 'string',
              pattern: '^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(.*)$',
              minLength: 5,
            },
          },
        }),
      Action: z
        .literal('DescribeType')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['DescribeType'] },
          },
        }),
      Version: z
        .literal('2010-05-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2010-05-15'] },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success', content: { 'text/xml': { schema: DescribeTypeOutputSchema } } },
    480: {
      description: 'CFNRegistryException',
      content: { 'text/xml': { schema: CFNRegistryExceptionSchema } },
    },
    481: {
      description: 'TypeNotFoundException',
      content: { 'text/xml': { schema: TypeNotFoundExceptionSchema } },
    },
  },
})

