export const getActionRollbackStackRoute = createRoute({
  method: 'get',
  path: '/#Action=RollbackStack',
  description:
    "<p>When specifying <code>RollbackStack</code>, you preserve the state of previously provisioned resources when an operation fails. You can check the status of the stack through the <a>DescribeStacks</a> operation.</p> <p>Rolls back the specified stack to the last known stable state from <code>CREATE_FAILED</code> or <code>UPDATE_FAILED</code> stack statuses.</p> <p>This operation will delete a stack if it doesn't contain a last known stable state. A last known stable state includes any status in a <code>*_COMPLETE</code>. This includes the following stack statuses.</p> <ul> <li> <p> <code>CREATE_COMPLETE</code> </p> </li> <li> <p> <code>UPDATE_COMPLETE</code> </p> </li> <li> <p> <code>UPDATE_ROLLBACK_COMPLETE</code> </p> </li> <li> <p> <code>IMPORT_COMPLETE</code> </p> </li> <li> <p> <code>IMPORT_ROLLBACK_COMPLETE</code> </p> </li> </ul>",
  operationId: 'GET_RollbackStack',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      StackName: z
        .string()
        .regex(/([a-zA-Z][-a-zA-Z0-9]*)|(arn:\b(aws|aws-us-gov|aws-cn)\b:[-a-zA-Z0-9:\/._+]*)/)
        .min(1)
        .openapi({
          param: {
            name: 'StackName',
            in: 'query',
            required: true,
            description: "The name that's associated with the stack.",
            schema: {
              type: 'string',
              pattern:
                '([a-zA-Z][-a-zA-Z0-9]*)|(arn:\\b(aws|aws-us-gov|aws-cn)\\b:[-a-zA-Z0-9:/._+]*)',
              minLength: 1,
            },
          },
        }),
      RoleARN: z
        .string()
        .min(20)
        .max(2048)
        .exactOptional()
        .openapi({
          param: {
            name: 'RoleARN',
            in: 'query',
            required: false,
            description:
              'The Amazon Resource Name (ARN) of an Identity and Access Management role that CloudFormation assumes to rollback the stack.',
            schema: { type: 'string', minLength: 20, maxLength: 2048 },
          },
        }),
      ClientRequestToken: z
        .string()
        .regex(/[a-zA-Z0-9][-a-zA-Z0-9]*/)
        .min(1)
        .max(128)
        .exactOptional()
        .openapi({
          param: {
            name: 'ClientRequestToken',
            in: 'query',
            required: false,
            description: 'A unique identifier for this <code>RollbackStack</code> request.',
            schema: {
              type: 'string',
              pattern: '[a-zA-Z0-9][-a-zA-Z0-9]*',
              minLength: 1,
              maxLength: 128,
            },
          },
        }),
      RetainExceptOnCreate: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'RetainExceptOnCreate',
            in: 'query',
            required: false,
            description:
              'This deletion policy deletes newly created resources, but retains existing resources, when a stack operation is rolled back. This ensures new, empty, and unused resources are deleted, while critical resources and their data are retained. <code>RetainExceptOnCreate</code> can be specified for any resource that supports the <a href="https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/aws-attribute-deletionpolicy.html"> DeletionPolicy</a> attribute.',
            schema: { type: 'boolean' },
          },
        }),
      Action: z
        .literal('RollbackStack')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['RollbackStack'] },
          },
        }),
      Version: z
        .literal('2010-05-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2010-05-15'] },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success', content: { 'text/xml': { schema: RollbackStackOutputSchema } } },
    480: {
      description: 'TokenAlreadyExistsException',
      content: { 'text/xml': { schema: TokenAlreadyExistsExceptionSchema } },
    },
  },
})

