export const getActionSignalResourceRoute = createRoute({
  method: 'get',
  path: '/#Action=SignalResource',
  description:
    "Sends a signal to the specified resource with a success or failure status. You can use the <code>SignalResource</code> operation in conjunction with a creation policy or update policy. CloudFormation doesn't proceed with a stack creation or update until resources receive the required number of signals or the timeout period is exceeded. The <code>SignalResource</code> operation is useful in cases where you want to send signals from anywhere other than an Amazon EC2 instance.",
  operationId: 'GET_SignalResource',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      StackName: z
        .string()
        .regex(/([a-zA-Z][-a-zA-Z0-9]*)|(arn:\b(aws|aws-us-gov|aws-cn)\b:[-a-zA-Z0-9:\/._+]*)/)
        .min(1)
        .openapi({
          param: {
            name: 'StackName',
            in: 'query',
            required: true,
            description:
              'The stack name or unique stack ID that includes the resource that you want to signal.',
            schema: {
              type: 'string',
              pattern:
                '([a-zA-Z][-a-zA-Z0-9]*)|(arn:\\b(aws|aws-us-gov|aws-cn)\\b:[-a-zA-Z0-9:/._+]*)',
              minLength: 1,
            },
          },
        }),
      LogicalResourceId: z
        .string()
        .openapi({
          param: {
            name: 'LogicalResourceId',
            in: 'query',
            required: true,
            description:
              'The logical ID of the resource that you want to signal. The logical ID is the name of the resource that given in the template.',
            schema: { type: 'string' },
          },
        }),
      UniqueId: z
        .string()
        .min(1)
        .max(64)
        .openapi({
          param: {
            name: 'UniqueId',
            in: 'query',
            required: true,
            description:
              'A unique ID of the signal. When you signal Amazon EC2 instances or Auto Scaling groups, specify the instance ID that you are signaling as the unique ID. If you send multiple signals to a single resource (such as signaling a wait condition), each signal requires a different unique ID.',
            schema: { type: 'string', minLength: 1, maxLength: 64 },
          },
        }),
      Status: z
        .enum(['SUCCESS', 'FAILURE'])
        .openapi({
          param: {
            name: 'Status',
            in: 'query',
            required: true,
            description:
              'The status of the signal, which is either success or failure. A failure signal causes CloudFormation to immediately fail the stack creation or update.',
            schema: { type: 'string', enum: ['SUCCESS', 'FAILURE'] },
          },
        }),
      Action: z
        .literal('SignalResource')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['SignalResource'] },
          },
        }),
      Version: z
        .literal('2010-05-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2010-05-15'] },
          },
        }),
    }),
  },
  responses: { 200: { description: 'Success' } },
})

