export const getActionUpdateTerminationProtectionRoute = createRoute({
  method: 'get',
  path: '/#Action=UpdateTerminationProtection',
  description:
    '<p>Updates termination protection for the specified stack. If a user attempts to delete a stack with termination protection enabled, the operation fails and the stack remains unchanged. For more information, see <a href="https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/using-cfn-protect-stacks.html">Protecting a Stack From Being Deleted</a> in the <i>CloudFormation User Guide</i>.</p> <p>For <a href="https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/using-cfn-nested-stacks.html">nested stacks</a>, termination protection is set on the root stack and can\'t be changed directly on the nested stack.</p>',
  operationId: 'GET_UpdateTerminationProtection',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      EnableTerminationProtection: z
        .stringbool()
        .openapi({
          param: {
            name: 'EnableTerminationProtection',
            in: 'query',
            required: true,
            description: 'Whether to enable termination protection on the specified stack.',
            schema: { type: 'boolean' },
          },
        }),
      StackName: z
        .string()
        .regex(/([a-zA-Z][-a-zA-Z0-9]*)|(arn:\b(aws|aws-us-gov|aws-cn)\b:[-a-zA-Z0-9:\/._+]*)/)
        .min(1)
        .openapi({
          param: {
            name: 'StackName',
            in: 'query',
            required: true,
            description:
              'The name or unique ID of the stack for which you want to set termination protection.',
            schema: {
              type: 'string',
              pattern:
                '([a-zA-Z][-a-zA-Z0-9]*)|(arn:\\b(aws|aws-us-gov|aws-cn)\\b:[-a-zA-Z0-9:/._+]*)',
              minLength: 1,
            },
          },
        }),
      Action: z
        .literal('UpdateTerminationProtection')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['UpdateTerminationProtection'] },
          },
        }),
      Version: z
        .literal('2010-05-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2010-05-15'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: UpdateTerminationProtectionOutputSchema } },
    },
  },
})

